 s=texts[key];m=re.search(r'^( *)def '+re.escape(name)+r'(?=[( ;\n])[^\n]*\n',s,re.M);assert m,(key,name);z=m.end() if '; end' in m.group(0) else m.end()+re.search(r'^'+m.group(1)+r'end\s*$',s[m.end():],re.M).end(); uid=key+':'+name; units.append(dict(id=uid,source_identity_key=key,range=[s.count('\n',0,m.start())+1,s.count('\n',0,z)+1],text=s[m.start():z],complete_definition=True)); return uid
